    ggml_metal_buffer_t res = calloc(1, sizeof(struct ggml_metal_buffer));
    if (!res) return NULL;
    res->dev = dev;
    res->all_data = metal.contents;
    res->all_size = metal.length;
    res->is_shared = true;
    res->owned = false;
    res->n_buffers = 1;
    res->buffers[0].data = metal.contents;
    res->buffers[0].size = metal.length;
    res->buffers[0].metal = [metal retain];
    res->use_residency_sets = ggml_metal_device_get_props(dev)->use_residency_sets;
    if (!ggml_metal_buffer_rset_init(res)) {
        ggml_metal_buffer_rset_free(res);
        [res->buffers[0].metal release];
