// Cold specialization of the exact packed NVFP4 operation, no payload access.
static bool ggml_hyle_metal_prepare_packed_op(ggml_backend_t backend, const ggml_tensor * op, bool * unsupported) {
    if (op->op != GGML_OP_MUL_MAT && op->op != GGML_OP_MUL_MAT_ID &&
        op->op != GGML_OP_GET_ROWS) return true;
    if (!op->src[0] || op->src[0]->type != GGML_TYPE_NVFP4) return true;
    auto dev = (ggml_metal_device_t) backend->device->context;
    auto lib = ggml_metal_device_get_library(dev);
    if (!lib) return false;
    if (!ggml_metal_device_supports_op(dev, op)) { *unsupported = true; return false; }
    const auto * props = ggml_metal_device_get_props(dev);
    ggml_metal_pipeline_with_params p{};
    size_t threads = 0;
    if (op->op == GGML_OP_GET_ROWS) {
        p = ggml_metal_library_get_pipeline_get_rows(lib, GGML_TYPE_NVFP4);
        if (p.allocation_failed) throw std::bad_alloc();
        if (!p.pipeline) return false;
        threads = std::min<int64_t>(op->src[0]->ne[0]/16,
                                  ggml_metal_pipeline_max_theads_per_threadgroup(p));
    } else if (op->op == GGML_OP_MUL_MAT) {
        if (ggml_metal_op_mul_mat_use_mm(op, props->has_simdgroup_mm)) {
            p = ggml_metal_library_get_pipeline_mul_mm(lib, op);
        } else {
            p = ggml_metal_library_get_pipeline_mul_mv(lib, op);
        }
        threads = 32*p.nsg;
    } else if (op->op == GGML_OP_MUL_MAT_ID) {
        if (ggml_metal_op_mul_mat_id_use_mm(op, props->has_simdgroup_mm)) {
            auto map = ggml_metal_library_get_pipeline_mul_mm_id_map0(lib, op->src[0]->ne[2], op->src[2]->ne[0]);
            if (map.allocation_failed) throw std::bad_alloc();
            if (!map.pipeline) return false;
            if (!ggml_metal_pipeline_supports_launch(map, op->src[0]->ne[2],
                    props->max_theadgroup_memory_size, false)) { *unsupported = true; return false; }
            p = ggml_metal_library_get_pipeline_mul_mm_id(lib, op);
            threads = 128;
        } else {
            p = ggml_metal_library_get_pipeline_mul_mv_id(lib, op);
            threads = 32*p.nsg;
        }
    } else return false;
    if (p.allocation_failed) throw std::bad_alloc();
    if (!p.pipeline) return false;
    *unsupported = !ggml_metal_pipeline_supports_launch(p, threads,
        props->max_theadgroup_memory_size, op->op != GGML_OP_GET_ROWS);
    return !*unsupported;
}

extern "C" bool ggml_hyle_metal_prepare_graph(ggml_backend_t backend, ggml_cgraph * graph, bool * unsupported) {
    *unsupported = false;
    for (int i = 0; i < ggml_graph_n_nodes(graph); ++i) {
        if (!ggml_hyle_metal_prepare_packed_op(backend, ggml_graph_node(graph, i), unsupported)) return false;
    }
    return true;
}

